-- composition of rule kernels grouping_sets x statistics_propagation (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100 AS c0, 16 AS c1 UNION SELECT 27 AS c0, 17 AS c1), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100 AS c0, 16 AS c1 UNION SELECT 27 AS c0, 17 AS c1) AS ka) + (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS kb)
